import re
checks = [
 ("产品需求说明书.md",424,"系统生成 MinIO 对象名称和唯一文档版本号（同一需求下从 1 开始递增）"),
 ("产品需求说明书.md",396,"系统调用外部 HARNESS 服务创建 BRD 协作会话（用户同步、Token 获取、工作空间配置、群聊会话创建）"),
 ("产品需求说明书.md",423,"业务用户上传 BRD 文档：指定需求 ID 和文档类型（BRD），系统校验必填项和文档类型合法性"),
 ("产品需求说明书.md",424,"调用 MinIO SDK 上传文件并构建访问 URL，在文档版本表中插入新记录并更新需求的当前 BRD 文档版本 ID"),
 ("产品需求说明书.md",397,"系统构建需求实体并插入数据库，设置需求 ID、标题（未提供时自动生成默认标题）"),
 ("产品需求说明书.md",397,"记录操作日志"),
 ("需求平台前端设计文档.md",594,"workspaceId"),
]
def norm(s): return re.sub(r"\s+"," ",s).strip()
cache={}
for f,ln,q in checks:
    if f not in cache: cache[f]=open(f,encoding="utf-8").read().splitlines()
    lines=cache[f]
    ok = norm(q) in norm(lines[ln-1])
    print(("OK  " if ok else "FAIL ")+f+":"+str(ln))
    if not ok: print("   LINE:",lines[ln-1])
EOF

